e.sources.push(...[{"id":"close-30","title":"국내 주식 마감·마켓 클로징30일","publisher":"신한·미래에셋 제공 PDF","publishedAt":"2026-10-30","observedAt":"한국30일 마감","url":null,"verification":"제공 PDF 마감표·본문 확인","note":"bbs_1793346614713·doc_2026-11-01_22-43-02(내부30일). 장중/종가·개별주 시각차이 보존."},{"id":"brief-30","title":"글로벌 마켓 브리핑30일","publisher":"미래에셋2148122","publishedAt":"2026-10-30","observedAt":"미국29일 본장·FICC/장후","url":null,"verification":"제공 PDF 마감표·본문 확인","note":"알파벳-12.64%,나스닥-1.38%,미10Y4.9369%. SOX 값중복소수점 제외."},{"id":"amazon-29","title":"Amazon Third Quarter Results","publisher":"Amazon IR","publishedAt":"2026-10-29 미국장후","observedAt":"분기 AWS / 전사 TTM 현금","url":"https://ir.aboutamazon.com/news-release/news-release-details/2026/Amazon-com-Announces-Third-Quarter-Results/","verification":"원문 확인 / 기관 관측은 별도 표시","note":"TTM OCF 증가·FCF적자. 분기와 TTM 혼용 금지."},{"id":"pce-29","title":"Personal Income and Outlays September","publisher":"BEA","publishedAt":"2026-10-29 08:30 EDT","observedAt":"9월 /11월1일 원문 새 확인","url":"https://www.bea.gov/news/2026/personal-income-and-outlays-september-2026","verification":"원문 확인 / 기관 관측은 별도 표시","note":"29일 보고서의 당시 접근보류 기록은 유지."},{"id":"meta-outlook-30","title":"S&P revises Meta outlook to negative","publisher":"Reuters / MarketScreener","publishedAt":"2026-10-30 미국 / 한국31일 전달","observedAt":"전망 변경·미래FOCF 추정","url":"https://www.marketscreener.com/news/s-p-global-revises-meta-s-outlook-to-negative-on-ai-spending-cash-flow-worries-ce785fdbd081ff2c","verification":"원문 확인 / 기관 관측은 별도 표시","note":"S&P 원문 대신 Reuters 보도 확인. 등급강등·실제부도 아님. 회사 반론 병기."},{"id":"jpm-weekend-01","title":"More Equity, Less Leverage","publisher":"제공 Macro Trader / JPMorgan","publishedAt":"2026-11-01 21:28 KST","observedAt":"제공 분석의 표본·전망","url":null,"verification":"제공 PDF 마감표·본문 확인","note":"원보고서 별도 미확보. 채권잔액/신규발행·LTC/기업레버리지·주주/채권자 효과 분리."}]);
e.casebook.sections.push(...[{"title":"10월30일 후속 기록 — 알파벳 본장 급락에서 한국 반도체 매도로","paragraphs":["알파벳은 본장에서12.64% 하락했다. 전날 장후의 FCF 적자 확대 우려가 실제 본장 가격에 반영된 관측이다. 그러나 검색 성장 둔화와 예상 대비 실적, 높은 투자 계획도 함께 쟁점이었으므로 전체 낙폭을 현금흐름 한 항목의 효과로 계산하지 않는다. 매출이 늘어도 투자 후 남는 현금과 기대한 성장에 못 미치면 평가배수는 낮아질 수 있다.","장후 아마존과 인텔의 하락은 미국29일 본장 지수에 포함되지 않지만 한국30일 개장 전에는 알려졌다. 신한 마감은 각각 약-7.3%·-23.0%로 기록했고 해외 데일리에는-8.7%·약-20%도 있어 관측 시각별 호가로 구분한다. 한국30일 밤 전달된 인텔 장중 최대-26%는 또 다른 구간이며 확정 종가가 아니다.","신한 집계의 코스피 외국인-1조6,168억원·기관+7,432억원·개인+6,199억원이었다. 코스닥은 외국인-277억원·기관-1,377억원·개인+1,688억원이다. 전날 코스피 외국인이 소폭 매수했던 것과 달리 오늘은 큰 매도로 바뀌었다. 기관의 순매수가 있었어도 가격 하락을 완전히 흡수하지 못했다.","미국 고객사의 현금 부담이 커지면 장래 투자 지속성에 대한 할인율뿐 아니라 한국 공급사의 주문·이익 지속 기간에 대한 신뢰도 달라질 수 있다. 실제 CapEx 취소가 확인되기 전에 기대가 먼저 조정되는 경로다. 오늘 기관들은 이 경로와 외국인 수급을 함께 강조했지만 이미 체결한 메모리 계약이 취소됐다는 자료는 아니다."],"sourceIds":["close-30","brief-30","alphabet-28"]},{"title":"10월30일 후속 기록 — 아마존의 영업현금 증가와 투자 후 적자","paragraphs":["아마존 공식 발표의3분기 AWS 매출은460억달러(+39.3%), 영업이익은178억달러였다. 하지만 최근12개월 FCF는-424억달러로 전년동기+148억달러에서 악화됐다. 분기 사업부 영업이익과 전사12개월 현금흐름의 범위가 달라 두 숫자를 직접 뺄 수 없다. <a href=\"https://ir.aboutamazon.com/news-release/news-release-details/2026/Amazon-com-Announces-Third-Quarter-Results/\" target=\"_blank\" rel=\"noopener noreferrer\">아마존 공식 실적</a>.","같은 발표에서12개월 영업현금흐름은1,683억달러로29% 증가했다. 따라서 현금창출 자체가 사라졌다는 표현보다 자산 취득 증가가 영업현금을 넘어섰다는 설명이 정확하다. 순유형자산 취득액의 전년 대비948억달러 증가는 주로 AI 투자를 반영했다는 회사 설명이다. 투자 지속에는 본업 현금 외 재원이나 지출 속도 조절이 중요해진다.","MS는 현금 유형자산 취득 차감 후 분기 FCF 흑자를 유지했다. 회사채 발행 보도도 있었지만 차입이 곧 지급불능을 뜻하지 않는다. 기업의 현금·리스·조달 만기와 차입 비용을 함께 봐야 한다. 반대로 우량기업이 발행에 성공했다고 네오클라우드와 미완공 프로젝트의 차환도 같은 조건으로 가능하다고 볼 수 없다.","인텔은 데이터센터 부문의 고성장에도 다음 분기 매출150억~160억달러 전망이 약170억달러의 시장 눈높이에 미치지 못했다는 기관 설명이다. PC 수요와 생산 차질을 함께 보므로 이를 AI 최종 수요만의 붕괴로 읽으면 과도하다. 메모리 가격 상승은 공급사 이익에 유리할 수 있어도 기기 원가와 소비 수요에는 부담이 될 수 있다."],"sourceIds":["amazon-29","close-30","msft-28"]},{"title":"10월30일 후속 기록 — 금리가 내려도 성장주의 가격은 내려갔다","paragraphs":["미래에셋 FICC 관측은 미2년물4.5979%(-9.96bp), 10년물4.9369%(-8.06bp), 30년물5.2996%(-4.41bp)였다. 강한 GDP와 높은 물가에도 금리는 하락했다. 주식 불안에 따른 국채 수요가 우세했다는 기관 해석이며, 이 움직임을 물가 문제가 해결됐거나 정책 인하가 확정됐다는 뜻으로 바꾸지 않는다.","BEA 원문을 이번에 확인했다. 9월 명목 소비는 전월 대비0.5% 늘었지만 실질 소비 증가는0.1% 미만으로 표에서는0.0%, 실질 가처분소득은0.3% 감소했다. PCE 물가는 전월비0.5%·전년비3.6%, 근원은0.3%·3.1%였다. 지출액 확대와 구매량 정체가 공존했다. <a href=\"https://www.bea.gov/news/2026/personal-income-and-outlays-september-2026\" target=\"_blank\" rel=\"noopener noreferrer\">BEA9월 소득·지출</a>.","높은 성장과 물가에도 위험회피로 금리가 내려갈 때 장기금리 하락은 주식의 좋은 뉴스만은 아니다. 고객의 현금 회수와 투자 지속성에 대한 요구가 더 크게 바뀌면 할인율 하락의 이익보다 기대 현금흐름 축소가 우세할 수 있다. 이번에는 검색·PC·가이던스와 포지션 조정도 겹쳐 단일 원인으로 분리할 수 없다.","이 관측은 모든 AI 투자가 이미 취소됐다는 증거가 아니다. AWS 이익, MS 현금흐름 흑자와 공급사 장기계약은 반대 근거로 남는다. 발주 축소·완공·이용률·최종 사용자 지출이 실제로 바뀌는지를 다음 단계에서 확인해야 한다."],"sourceIds":["brief-30","pce-29","amazon-29","msft-28"]},{"title":"11월1일 사후 보충 — 신용평가의 경고와 주식 조달의 양면성","paragraphs":["Reuters가 전한 S&P의 메타 전망 변경은 안정적에서 부정적으로의 조정이다. AA- 등급 자체의 강등이나 실제 부도와는 다르다. 2026·2027년 FOCF 적자390억·710억달러는 평가사 전망이며 회사는 AI 수익화 평가에 반대했다. 조달 흥행만으로 투자 후 현금의 질문이 사라지지 않았다는 후속 근거다. <a href=\"https://www.marketscreener.com/news/s-p-global-revises-meta-s-outlook-to-negative-on-ai-spending-cash-flow-worries-ce785fdbd081ff2c\" target=\"_blank\" rel=\"noopener noreferrer\">S&P 조치에 관한 Reuters 보도</a>.","11월1일 전달된 JPMorgan 분석은 증자가 미래 채권 공급과 레버리지 부담을 낮출 수 있다고 봤다. 이는 채권자에게 유리해도 주주의 희석·수익률에는 다른 결과를 낳을 수 있다는 해석이다. 추적 채권 잔액6,290억달러를 올해 신규 차입액으로, 사업비 대비 대출비율을 기업 부채비율로 바꾸지 않는다. 해당 분석은 금요일 이후 보충 자료이며 그날 장세의 사전 원인이 아니다.","평가 전망 변경은 기존 현금 우려가 신용 평가에도 반영됐다는 새로운 관측이지만 한국30일 낮 매도의 사전 재료가 아니다. 평가사 예측이 실제 현금 결과와 일치할지는 아직 미정이며 회사의 반론도 함께 남긴다. 전망 변경 직후 CDS·채권·주가의 동일시점 반응을 확보하지 못해 별도 독립 충격으로 분리하지 않는다.","새 자본의 투입은 부채의 완충력을 높이지만 기존 주주의 몫을 줄일 수도 있다. 같은 회사의 주식과 회사채가 서로 다른 반응을 보일 수 있는 조건이다. 프로젝트의 담보·상환순위·보증 조건을 확인하지 않은 채 임차인 신용등급을 모든 연계 채권에 복사하지 않는다."],"sourceIds":["meta-outlook-30","jpm-weekend-01"]}]);
e.updates.push({"date":"2026-11-01","title":"10월30일 한·미 전이와 주말 신용평가 보충","paragraphs":["기존 발생일·한국 반영일·15개 본문과 과거 관측은 보존한다. 미국29본장→장후→한국30일, 한국31일/11월1일 신규 자료의 시차를 구분해4개 절을 추가했다. 독립 뉴스 사건을 늘리지 않고 같은 현금 회수 충격의 후속으로 연결한다."],"sourceIds":["close-30","brief-30","amazon-29","pce-29","meta-outlook-30","jpm-weekend-01"]});
