{const a=window.MARKET_LEDGER.macroEvents,e=a.events.find(e=>e.id==='2026-10-21-lam-meta-ai-earnings-shock');e.sources.push(...[{"id":"mirae-brief-nov02","title":"미국10월30일 본장·FICC","publisher":"미래에셋2148202","publishedAt":"2026-11-02","observedAt":"미국10/30본장·기관호가","url":null,"verification":"제공표·본문 확인","note":"SOX10688.80-7.20·VIX19.42;미국본장과한국2일분리."},{"id":"korea-close-nov02","title":"반도체 악재 버틴 한국 마감","publisher":"신한bbs_1793606845722·미래에셋doc_00-14-09","publishedAt":"2026-11-02","observedAt":"한국2일마감","url":null,"verification":"두마감표 이미지 대조","note":"연기금8930억원은지난금요일기록.매입3650억원은기관자료."},{"id":"export-nov01-confirmed","title":"10월수출 원문 새 확인","publisher":"산업통상부/정책브리핑","publishedAt":"2026-11-02 게시·11/1발표","observedAt":"10월수출·11/3검토","url":"https://m.korea.kr/news/policyNewsView.do?newsId=148974754","verification":"공식 본문 확인","note":"역대두번째·일평균76.1%.과거접근보류당시기록유지."},{"id":"square-nov02","title":"Record-high Shareholder Returns","publisher":"SK Square 공식뉴스","publishedAt":"2026-11-02","observedAt":"4.3조원이상계획","url":"https://www.sksquare.com/eng/news/ajax/loadNewsList.do","verification":"공식뉴스목록 요약 확인","note":"6.2조배당수입→4.3조이상.최종집행아님."},{"id":"oracle-nov02-after","title":"예비 보통주·동시선순위채 공시","publisher":"Oracle 공시/Publicnow재게시","publishedAt":"2026-11-02 미국","observedAt":"한국2일마감후","url":"https://www.publicnow.com/view/47946C24AA7F4BBD0EDBB9B63F389C9ECCAEDCCF","verification":"검색노출 공시문 확인·본문직접403","note":"각100억달러·서로결제조건아님.최종조건/수취완료미확인."},{"id":"anthropic-nov02-after","title":"수정실적·약정 전달","publisher":"TNBfolio 제공 전문","publishedAt":"2026-11-02 23:29~11/3 00:10 KST","observedAt":"3분기·기준일후약정","url":null,"verification":"전달자료·수정S1재무주석미대조","note":"매출170억/영업손실5.67억/조정25억·약정8954억.현금/부채동일시아님."}]);e.casebook.sections.push(...[{"title":"11월2일 후속 기록 — 미국30일 반도체 매도와 국내의 다른 반응","paragraphs":["미국10월30일 다우51,770.31(-1.09%), S&P5007,580.07(-1.82%), 나스닥25,436.99(-2.86%)로 마감했다. SOX10,688.80(-7.20%), 러셀2000 2,811.84(-1.66%), VIX19.42(+12.91%)였다(미래에셋11월2일 브리핑). 이번에 확보한 반도체·변동성 마감도 한국 월요일의 선행 정보로 기록한다.","인텔은28.58%, 샌디스크는13.47%, 하이닉스 ADR은7.95% 하락했다. 인텔의 약한 다음 분기 전망은 이미 한국 금요일 개장 전 장후 가격으로 알려진 재료였지만 미국 본장의 추가 매도와 메모리 동반 약세는 이후 관측이다. 같은 발표를 새 충격으로 두 번 세지 않으면서 정보의 강화는 남긴다.","아마존은 장중6% 가까이 밀렸다가1.41% 하락으로 마쳤다는 브리핑이다. 앞선 장후 급락률과 본장 종가가 다르다. AWS의 매출·이익 성장과 전사 투자 후 현금 부담을 함께 읽어야 하며, 반등한 종가만으로 투자 회수 우려가 해소됐다고 해석하기는 어렵다.","미국 기술주 가격은 고객의 실적·현금 회수에 대한 평가가 공급망 전체로 번진 관측이다. 하지만 한국 월요일은 같은 가격을 반복하지 않았다. 앞서 알려진 인텔의 장후 전망과 새 본장 매도의 구분, 국내의 별도 매수 재원이 다음 반응을 이해하는 연결고리다."],"sourceIds":["mirae-brief-nov02","korea-close-nov02"]},{"title":"11월2일 한국 — 현금 배분과 기관 흡수가 만든 반론","paragraphs":["신한 마감의 코스피 기관+1조2,331억원, 외국인-3,696억원, 개인-1조3,465억원이었다. 코스닥은 기관+623억원, 외국인-321억원, 개인-261억원이다. 오늘 반등은 외국인이 한국 주식 전체에 복귀해서라기보다 기관과 기타법인의 흡수가 강해진 결과라는 설명이 더 맞는다.","시장 폭도 코스피 상승653·하락230개, 코스닥 상승1,115·하락553개로 개선됐다. 반도체 대형주만 올라 지수를 지킨30일과 달리 여러 업종으로 가격 회복이 퍼졌다. 이 확산은 관측된 진전이지만 하루 결과를 지속적인 외부 자금 유입으로 바꿀 근거는 아직 없다.","SK스퀘어는 하이닉스 배당수입6.2조원 이상 가운데4.3조원 이상을 주주에게 돌려줄 계획을 공식 뉴스에서 밝혔다. 자회사에서 지주회사로, 다시 주주로 이어지는 현금 배분의 연결고리다. 계획 발표와 실제 취득·소각·배당 집행은 구분하며 하이닉스 환원 총액에 다시 더해 공급망 전체의 새 현금으로 세지 않는다. SK스퀘어 공식 환원 발표 목록.","공급사에서 주주로 향하는 실제 매수 재원과 강한 수출은 해외 고객 신용 우려를 완충할 수 있었다. 이는 모든 AI 수요가 무너졌다는 주장의 반론이다. 그러나 하루의 반등과 양 시장 외국인 매도는 함께 남아 고객 ROI·새 조달의 정상화를 입증하지는 않는다. 현금 배분의 구체성과 매수의 지속을 다음 조건으로 둔다."],"sourceIds":["korea-close-nov02","export-nov01-confirmed","square-nov02"]},{"title":"11월2일 마감 후 — 조달과 수정 실적은 새 정보 집합이다","paragraphs":["한국2일 마감 이후 전달된 오라클 신주100억달러·선순위채100억달러 계획은 AI 투자의 자본구조가 다시 쟁점이 됐다는 소식이다. 검색으로 확인한 회사 공시 재게시의 예비 투자설명서는 두 거래가 서로의 결제에 조건부가 아니라고 명시했다. 본문 직접 접근은 제한돼 최종 조건·결제를 확인한 거래로 쓰지 않는다. 오라클 예비 투자설명서 재게시.","밤의 앤트로픽 수정 공시 전달은3분기 매출 약170억달러, 영업손실5.67억달러와 조정 영업이익25억달러를 함께 소개했다. 회계상 손실·조정 이익·현금흐름은 서로 다른 지표다. 약8,954억달러 구매·리스 약정 역시 전부 현재 부채나 그 분기에 지급할 비용은 아니다. 수정 S-1 재무 주석 전체를 직접 대조하지 못한 수치는 제공 자료로 구분한다.","이 소식은 한국2일 상승의 사전 원인이 아니다. 조달의 규모보다 최종 발행 조건·자금 유입과 지급 일정, 회계·조정 이익이 실제 영업현금으로 연결되는지가 중요해졌다. 원문 주석 대조가 남은 전달 수치와 프리마켓 반응은 수준을 표시해 보존하고, 독립 충격으로 사건을 늘리지 않는다."],"sourceIds":["oracle-nov02-after","anthropic-nov02-after"]}]);e.reactions.push({"market":"미국반도체 / 한국주식·수급","window":"미국10/30본장→한국11/2마감","observation":"SOX-7.20%·Intel-28.58%; KS+2.24%·KQ+1.38%,기관KS+12,331억원·외인-3,696억원","interpretation":"추가 해외 매도에도 국내 현금배분·기관 흡수로 반등.고객현금위험해소·외인귀환과다름.","sourceIds":["mirae-brief-nov02","korea-close-nov02"]});e.timeline.push({"at":"2026-11-02 한국마감","session":"반대 근거·후속 관측","title":"국내 매수가 해외 충격을 흡수","paragraphs":["양시장폭개선·기관/자사주·환원,외국인매도병존.밤미국조달·실적은별도."],"sourceIds":["korea-close-nov02","square-nov02"]});e.updates.push({"date":"2026-11-03","title":"미국30일 본장·한국2일 반등과 밤의 새 자료","paragraphs":["이번에확보한주가·수급과공식수출·환원근거를날짜붙여추가.과거기록·사건발생일유지.선거전망·재정연설·채권전망은독립시장충격으로편입않음."],"sourceIds":["mirae-brief-nov02","korea-close-nov02","export-nov01-confirmed","square-nov02","oracle-nov02-after","anthropic-nov02-after"]});e.updatedAt='2026-11-03';e.casebook.editedAt='2026-11-03';a.updatedAt='2026-11-03';}

